using System.Net;
using System.Text.Json;
using ResourceHub.Tests.Infrastructure;

namespace ResourceHub.Tests;

public class ActiveAllocationTests(HubApiFactory factory) : IClassFixture<HubApiFactory>, IAsyncLifetime
{
    private readonly HttpClient _client = factory.CreateClient();
    private Scenario S => new(_client);

    private Guid _device;
    private Guid _license;
    private Guid _credits;
    private string _returnedToken = "";
    private string _keptToken = "";
    private string _closedTicketToken = "";

    /// <summary>
    /// Embedded Systems Lab gets: ticket A (2 devices, 1 key, 100 credits; one device returned)
    /// and ticket B (1 device, 50 credits; closed). CS501 gets ticket C (1 device), which must not show.
    /// </summary>
    public async Task InitializeAsync()
    {
        _device = await S.PhysicalAsync(units: 5, loanDays: 14);
        _license = await S.LicenseAsync("LAB-KEY-1", "LAB-KEY-2");
        _credits = await S.VoucherAsync(500m);

        var a = await AllocateForLabAsync(
            new { assetId = _device, quantity = 2 },
            new { assetId = _license, quantity = 1 },
            new { assetId = _credits, amount = 100m });
        var tokensA = Devices(a);
        (_returnedToken, _keptToken) = (tokensA[0], tokensA[1]);
        var returned = await _client.SendAsync(HttpMethod.Post, $"/api/v1/assets/{_device}/return", new { token = _returnedToken }, Ids.Admin);
        await returned.AssertStatusAsync(HttpStatusCode.OK);

        var b = await AllocateForLabAsync(
            new { assetId = _device, quantity = 1 },
            new { assetId = _credits, amount = 50m });
        _closedTicketToken = Devices(b)[0];
        await (await S.SetStatusAsync(b.Id("ticketId"), "closed", Ids.Admin)).AssertStatusAsync(HttpStatusCode.OK);

        await S.AllocatedTicketAsync(new { assetId = _device, quantity = 1 });
    }

    public Task DisposeAsync() => Task.CompletedTask;

    [DbFact]
    public async Task Lab_advisor_sees_active_allocations_for_their_lab()
    {
        var body = await GetAsync($"/api/v1/assets/allocations?researchLabId={Ids.LabEmbedded}", Ids.AdvisorRaman);

        Assert.Equal(Ids.LabEmbedded, body.Id("researchLabId"));
        var allocations = body.GetProperty("allocations").EnumerateArray().ToList();

        // Devices: not yet returned, whatever the ticket status (the closed ticket's device is still out).
        var tokens = allocations.Where(x => x.Str("assetType") == "physical")
            .SelectMany(x => x.GetProperty("devices").EnumerateArray()).Select(d => d.Str("token")).ToList();
        Assert.Equal(new[] { _keptToken, _closedTicketToken }.Order(), tokens.Order());
        Assert.DoesNotContain(_returnedToken, tokens);

        // License and voucher: only for tickets that are not closed.
        var key = Assert.Single(allocations.Where(x => x.Str("assetType") == "license"));
        Assert.Single(key.GetProperty("licenseKeys").EnumerateArray());
        var credit = Assert.Single(allocations.Where(x => x.Str("assetType") == "voucher"));
        Assert.Equal(100m, credit.GetProperty("amount").GetDecimal());

        var summary = body.GetProperty("summary");
        Assert.Equal(2, summary.GetProperty("devicesCheckedOut").GetInt32());
        Assert.Equal(0, summary.GetProperty("devicesOverdue").GetInt32());
        Assert.Equal(1, summary.GetProperty("licenseKeysAssigned").GetInt32());
        Assert.Equal(100m, summary.GetProperty("voucherCreditsAllocated").GetDecimal());
    }

